export function solveGraph(g){
 if(!g||!Array.isArray(g.nodes)||!g.nodes.length||g.nodes.length>100||new Set(g.nodes).size!==g.nodes.length||!Array.isArray(g.edges)||g.edges.length>1000||typeof g.directed!=='boolean')throw Error('Некорректный граф');
 const adj=Object.fromEntries(g.nodes.map(n=>[n,[]])),seen=new Set();
 for(const e of g.edges){if(!Object.hasOwn(adj,e.from)||!Object.hasOwn(adj,e.to)||typeof e.weight!=='number'||!Number.isFinite(e.weight))throw Error('Неизвестная вершина/вес');const key=JSON.stringify(g.directed?[e.from,e.to]:[e.from,e.to].sort());if(seen.has(key))throw Error('Неоднозначные рёбра');seen.add(key);adj[e.from].push([e.to,e.weight]);if(!g.directed)adj[e.to].push([e.from,e.weight]);}
 const order=(a,b)=>a<b?-1:a>b?1:0;
 if(g.kind==='mst_weight'){if(g.directed)throw Error('Нужен неориентированный граф');const p=Object.fromEntries(g.nodes.map(n=>[n,n]));const find=n=>p[n]===n?n:p[n]=find(p[n]);let total=0,count=0;for(const e of [...g.edges].sort((a,b)=>a.weight-b.weight)){const a=find(e.from),b=find(e.to);if(a!==b){p[a]=b;total+=e.weight;count++;}}if(count!==g.nodes.length-1)throw Error('Граф несвязный');return String(total);}
 if(g.kind==='prim_edges'){if(g.directed||!Object.hasOwn(adj,g.source))throw Error('Некорректный Прим');const used=new Set([g.source]),result=[];while(used.size<g.nodes.length){const candidates=[];for(const a of used)for(const [b,w]of adj[a])if(!used.has(b)){const [x,y]=[a,b].sort();candidates.push([w,x,y,b]);}candidates.sort((a,b)=>a[0]-b[0]||order(a[1],b[1])||order(a[2],b[2]));if(!candidates.length)throw Error('Граф несвязный');const [w,a,b,n]=candidates[0];used.add(n);result.push(a+b);}return result.join(',');}
 if(g.kind==='dijkstra_distance'||g.kind==='dijkstra_order'){if(!Object.hasOwn(adj,g.source)||g.edges.some(e=>e.weight<0))throw Error('Дейкстра: нужны неотрицательные веса');const d=Object.fromEntries(g.nodes.map(n=>[n,Infinity]));d[g.source]=0;const used=new Set(),result=[];while(true){const a=g.nodes.filter(n=>!used.has(n)&&Number.isFinite(d[n])).sort((a,b)=>d[a]-d[b]||order(a,b))[0];if(a===undefined)break;used.add(a);result.push(a);for(const [b,w]of adj[a])if(d[a]+w<d[b])d[b]=d[a]+w;}if(g.kind==='dijkstra_order')return result.join(',');if(!Number.isFinite(d[g.target]))throw Error('Путь не найден');return String(d[g.target]);}
 if(g.kind==='kahn_order'){if(!g.directed)throw Error('Нужен ориентированный граф');const deg=Object.fromEntries(g.nodes.map(n=>[n,0]));for(const e of g.edges)deg[e.to]++;const result=[];while(result.length<g.nodes.length){const a=g.nodes.filter(n=>!result.includes(n)&&deg[n]===0).sort()[0];if(a===undefined)throw Error('Цикл');result.push(a);for(const [b]of adj[a])deg[b]--;}return result.join(',');}
 throw Error('Алгоритм не поддерживается');
}
export function checkedAnswer(item){if(item.readable===false)return {answer:'?',verified:false,note:'Условие прочитано ненадёжно'};if(!item.graph)return {answer:item.answer||'?',verified:false,note:'Ответ модели, без вычислительной проверки'};try{const value=solveGraph(item.graph),norm=s=>String(s).replace(/\s/g,'').replaceAll('→',',');const matches=item.graph.options.filter(o=>norm(o.value)===norm(value));return {answer:matches.length===1?matches[0].label:'?',verified:matches.length===1,note:'Вычислено: '+value};}catch(e){return {answer:'?',verified:false,note:e.message};}}
